/******************************************************************************
 * xaxi_can_controller_sinit.c - config table lookup
 * Generated by vivado-axi-ip.
 *
 * XAxiCanController_ConfigTable is generated by the tools into xaxi_can_controller_g.c:
 *   classic flow: by data/axi_can_controller.tcl
 *   SDT flow:     from data/axi_can_controller.yaml (NULL-Name terminated table)
 * Only linked when the application calls XAxiCanController_LookupConfig();
 * XAxiCanController_Initialize() does not need it.
 ******************************************************************************/
#include "xaxi_can_controller.h"
#ifndef SDT
#include "xparameters.h"
#endif

extern XAxiCanController_Config XAxiCanController_ConfigTable[];

#ifndef SDT
XAxiCanController_Config *XAxiCanController_LookupConfig(u16 DeviceId)
{
    u32 i;

    for (i = 0U; i < (u32)XPAR_XAXICANCONTROLLER_NUM_INSTANCES; i++) {
        if (XAxiCanController_ConfigTable[i].DeviceId == DeviceId) {
            return &XAxiCanController_ConfigTable[i];
        }
    }
    return NULL;
}
#else
XAxiCanController_Config *XAxiCanController_LookupConfig(UINTPTR BaseAddress)
{
    u32 i;

    for (i = 0U; XAxiCanController_ConfigTable[i].Name != NULL; i++) {
        if (XAxiCanController_ConfigTable[i].BaseAddress == BaseAddress || BaseAddress == 0U) {
            return &XAxiCanController_ConfigTable[i];
        }
    }
    return NULL;
}
#endif
